  "hi_Steady_Influential": [
    "\u0926\u0915\u094d\u0937 (DAKSH) \u0930\u093f\u092a\u094b\u0930\u094d\u091f",
    "\u0906\u092a\u0915\u0940 \u0935\u094d\u092f\u0915\u094d\u0924\u093f\u0924\u094d\u0935 \u0936\u0948\u0932\u0940\n\u092e\u0941\u0916\u094d\u092f \u0936\u0948\u0932\u0940: \u0938\u094d\u0925\u093f\u0930 (Steady)\n\u0926\u094d\u0935\u093f\u0924\u0940\u092f \u0936\u0948\u0932\u0940: \u092a\u094d\u0930\u092d\u093e\u0935\u0936\u093e\u0932\u0940 (Influential)",
    "\u092f\u0939 \u0930\u093f\u092a\u094b\u0930\u094d\u091f \u0906\u092a\u0915\u0947 \u092c\u093e\u0930\u0947 \u092e\u0947\u0902 \u092f\u0939 \u091c\u093e\u0928\u0915\u093e\u0930\u0940 \u0926\u0947\u0924\u0940 \u0939\u0948:\n\u2022 \u0906\u092a \u0905\u092a\u0928\u0947 \u0915\u093e\u092e \u092e\u0947\u0902 \u0936\u093e\u0902\u0924, \u0927\u0948\u0930\u094d\u092f\u0935\u093e\u0928 \u0914\u0930 \u0938\u0939\u092f\u094b\u0917\u0940 \u0939\u0948\u0902\u0964\n\u2022 \u0906\u092a \u0938\u092e\u0942\u0939 \u092e\u0947\u0902 \u0938\u093e\u092e\u0902\u091c\u0938\u094d\u092f \u0914\u0930 \u0938\u0939\u092f\u094b\u0917 \u092c\u0928\u093e\u090f \u0930\u0916\u0928\u093e \u092a\u0938\u0902\u0926 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902\u0964\n\u2022 \u0906\u092a \u092e\u093f\u0932\u0928\u0938\u093e\u0930 \u0939\u0948\u0902 \u0914\u0930 \u0932\u094b\u0917\u094b\u0902 \u0938\u0947 \u092c\u093e\u0924\u091a\u0940\u0924 \u0915\u0930\u0928\u0947 \u092e\u0947\u0902 \u0938\u0939\u091c \u0939\u0948\u0902\u0964\n\u2022 \u0906\u092a \u0938\u092e\u0942\u0939 \u0915\u0947 \u0905\u0928\u094d\u092f \u0938\u0926\u0938\u094d\u092f\u094b\u0902 \u0915\u094b \u092a\u094d\u0930\u0947\u0930\u093f\u0924 \u0914\u0930 \u092a\u094d\u0930\u094b\u0924\u094d\u0938\u093e\u0939\u093f\u0924 \u0915\u0930 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964\n\u2022 \u0906\u092a \u0938\u093e\u0925 \u092e\u093f\u0932\u0915\u0930 \u0915\u093e\u092e \u0915\u0930\u0928\u093e \u0914\u0930 \u0905\u091a\u094d\u091b\u0947 \u0938\u0902\u092c\u0902\u0927 \u092c\u0928\u093e\u0928\u093e \u092a\u0938\u0902\u0926 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902\u0964\n\u2022 \u0932\u094b\u0917 \u0906\u092a\u0915\u094b \u092e\u093f\u0932\u0928\u0938\u093e\u0930, \u092d\u0930\u094b\u0938\u0947\u092e\u0902\u0926 \u0914\u0930 \u0938\u092e\u0942\u0939 \u0917\u0924\u093f\u0935\u093f\u0927\u093f\u092f\u094b\u0902 \u092e\u0947\u0902 \u0938\u0939\u093e\u092f\u0915 \u092e\u093e\u0928\u0924\u0947 \u0939\u0948\u0902\u0964",
    "\u0906\u092a\u0915\u0940 8 \u092a\u094d\u0930\u0915\u093e\u0930 \u0915\u0940 \u092c\u0941\u0926\u094d\u0927\u093f\u092e\u0924\u094d\u0924\u093e (Intelligences)",
    "1. \u0924\u093e\u0930\u094d\u0915\u093f\u0915\u2013\u0938\u0902\u0916\u094d\u092f\u093e\u0924\u094d\u092e\u0915 \u092c\u0941\u0926\u094d\u0927\u093f\u092e\u0924\u094d\u0924\u093e (Logical\u2013Numerical) (\u0938\u0902\u0916\u094d\u092f\u093e \u0914\u0930 \u0939\u093f\u0938\u093e\u092c-\u0915\u093f\u0924\u093e\u092c)\n\u0938\u094d\u0924\u0930: \u0905\u091a\u094d\u091b\u093e\n\u2022 \u092c\u0941\u0928\u093f\u092f\u093e\u0926\u0940 \u0935\u093f\u0924\u094d\u0924\u0940\u092f \u0930\u093f\u0915\u0949\u0930\u094d\u0921 \u092c\u0928\u093e\u090f \u0930\u0916\u0928\u093e\n\u2022 \u092c\u091a\u0924 \u0914\u0930 \u090b\u0923 \u0915\u0947 \u0930\u093f\u0915\u0949\u0930\u094d\u0921 \u0915\u093e \u0939\u093f\u0938\u093e\u092c \u0930\u0916\u0928\u093e\n\u2022 \u0938\u094d\u091f\u0949\u0915 \u0914\u0930 \u0907\u0928\u094d\u0935\u0947\u0902\u091f\u0930\u0940 \u0930\u093f\u0915\u0949\u0930\u094d\u0921 \u092e\u0947\u0902 \u0938\u0939\u092f\u094b\u0917 \u0915\u0930\u0928\u093e\n\u2022 \u0938\u092e\u0942\u0939 \u0915\u0940 \u0935\u093f\u0924\u094d\u0924\u0940\u092f \u092f\u094b\u091c\u0928\u093e \u092e\u0947\u0902 \u0938\u0939\u093e\u092f\u0924\u093e \u0915\u0930\u0928\u093e",
    "2. \u092d\u093e\u0937\u093e\u0908 \u092c\u0941\u0926\u094d\u0927\u093f\u092e\u0924\u094d\u0924\u093e (Linguistic) (\u0938\u0902\u091a\u093e\u0930 \u0915\u094c\u0936\u0932)\n\u0938\u094d\u0924\u0930: \u0905\u091a\u094d\u091b\u093e\n\u2022 \u0938\u092e\u0942\u0939 \u092c\u0948\u0920\u0915\u094b\u0902 \u0914\u0930 \u091a\u0930\u094d\u091a\u093e\u0913\u0902 \u092e\u0947\u0902 \u092d\u093e\u0917 \u0932\u0947\u0928\u093e\n\u2022 \u0935\u093f\u091a\u093e\u0930\u094b\u0902 \u0914\u0930 \u091c\u093e\u0928\u0915\u093e\u0930\u0940 \u0915\u094b \u0938\u094d\u092a\u0937\u094d\u091f \u0930\u0942\u092a \u0938\u0947 \u0938\u092e\u091d\u093e\u0928\u093e\n\u2022 \u0917\u094d\u0930\u093e\u0939\u0915\u094b\u0902 \u0914\u0930 \u0905\u0927\u093f\u0915\u093e\u0930\u093f\u092f\u094b\u0902 \u0938\u0947 \u0938\u0902\u0935\u093e\u0926 \u0915\u0930\u0928\u093e\n\u2022 \u0930\u093f\u0915\u0949\u0930\u094d\u0921 \u0932\u093f\u0916\u0928\u0947 \u0914\u0930 \u0926\u0938\u094d\u0924\u093e\u0935\u0947\u091c\u093c \u092c\u0928\u093e\u0928\u0947 \u092e\u0947\u0902 \u0938\u0939\u092f\u094b\u0917 \u0915\u0930\u0928\u093e",
    "3. \u0935\u094d\u092f\u0915\u094d\u0924\u093f\u0917\u0924 \u0914\u0930 \u0938\u093e\u092e\u093e\u091c\u093f\u0915 \u092c\u0941\u0926\u094d\u0927\u093f\u092e\u0924\u094d\u0924\u093e (Personal & Social)\n\u0938\u094d\u0924\u0930: \u092e\u095b\u092c\u0942\u0924\n\u2022 \u0938\u092e\u0942\u0939 \u0915\u0947 \u0938\u0926\u0938\u094d\u092f\u094b\u0902 \u0915\u0947 \u0938\u093e\u0925 \u0905\u091a\u094d\u091b\u0947 \u0938\u0902\u092c\u0902\u0927 \u092c\u0928\u093e\u0928\u093e\n\u2022 \u0938\u092e\u0942\u0939 \u0917\u0924\u093f\u0935\u093f\u0927\u093f\u092f\u094b\u0902 \u092e\u0947\u0902 \u0938\u0915\u094d\u0930\u093f\u092f \u092d\u093e\u0917\u0940\u0926\u093e\u0930\u0940 \u0915\u0947 \u0932\u093f\u090f \u092a\u094d\u0930\u0947\u0930\u093f\u0924 \u0915\u0930\u0928\u093e\n\u2022 \u091f\u0940\u092e \u0915\u0947 \u0938\u092e\u0928\u094d\u0935\u092f \u0914\u0930 \u0938\u0939\u092f\u094b\u0917 \u092e\u0947\u0902 \u092e\u0926\u0926 \u0915\u0930\u0928\u093e\n\u2022 \u0938\u092e\u0942\u0939 \u092e\u0947\u0902 \u0938\u093e\u092e\u0902\u091c\u0938\u094d\u092f \u0914\u0930 \u0935\u093f\u0936\u094d\u0935\u093e\u0938 \u092c\u0928\u093e\u090f \u0930\u0916\u0928\u093e",
    "4. \u0936\u093e\u0930\u0940\u0930\u093f\u0915\u2013\u0915\u094c\u0936\u0932 \u092c\u0941\u0926\u094d\u0927\u093f\u092e\u0924\u094d\u0924\u093e (Bodily\u2013Kinesthetic) (\u0935\u094d\u092f\u093e\u0935\u0939\u093e\u0930\u093f\u0915 \u0915\u093e\u0930\u094d\u092f \u0915\u094c\u0936\u0932)\n\u0938\u094d\u0924\u0930: \u0905\u091a\u094d\u091b\u093e\n\u2022 \u0909\u0924\u094d\u092a\u093e\u0926\u0928 \u0938\u0947 \u091c\u0941\u0921\u093c\u0947 \u0915\u093e\u0930\u094d\u092f\n\u2022 \u0916\u093e\u0926\u094d\u092f \u092a\u094d\u0930\u0938\u0902\u0938\u094d\u0915\u0930\u0923 (\u092b\u093c\u0942\u0921 \u092a\u094d\u0930\u094b\u0938\u0947\u0938\u093f\u0902\u0917)\n\u2022 \u0938\u093f\u0932\u093e\u0908 \u0914\u0930 \u091f\u0947\u0932\u0930\u093f\u0902\u0917\n\u2022 \u092a\u0948\u0915\u093f\u0902\u0917 \u0914\u0930 \u092b\u093f\u0928\u093f\u0936\u093f\u0902\u0917 \u0915\u093e \u0915\u093e\u092e\n\u2022 \u0917\u0941\u0923\u0935\u0924\u094d\u0924\u093e \u0915\u0940 \u091c\u093e\u0902\u091a",
    "5. \u0926\u0943\u0936\u094d\u092f\u2013\u0938\u094d\u0925\u093e\u0928\u093f\u0915 \u092c\u0941\u0926\u094d\u0927\u093f\u092e\u0924\u094d\u0924\u093e (Visual\u2013Spatial) (\u0921\u093f\u091c\u093c\u093e\u0907\u0928 \u0914\u0930 \u0935\u094d\u092f\u0935\u0938\u094d\u0925\u093e)\n\u0938\u094d\u0924\u0930: \u092e\u0927\u094d\u092f\u092e\n\u2022 \u0909\u0924\u094d\u092a\u093e\u0926 \u0915\u0940 \u092a\u0948\u0915\u0947\u091c\u093f\u0902\u0917 \u0914\u0930 \u092a\u094d\u0930\u0938\u094d\u0924\u0941\u0924\u093f \u092e\u0947\u0902 \u0938\u0939\u092f\u094b\u0917\n\u2022 \u092c\u093e\u095b\u093e\u0930 \u092f\u093e \u0938\u094d\u091f\u0949\u0932 \u092a\u0930 \u0909\u0924\u094d\u092a\u093e\u0926\u094b\u0902 \u0915\u094b \u0938\u091c\u093e\u0928\u093e\n\u2022 \u0938\u093e\u092e\u0917\u094d\u0930\u0940 \u0915\u094b \u0928\u093e\u092a\u0928\u0947 \u0914\u0930 \u0935\u094d\u092f\u0935\u0938\u094d\u0925\u093f\u0924 \u0915\u0930\u0928\u0947 \u092e\u0947\u0902 \u092e\u0926\u0926 \u0915\u0930\u0928\u093e",
    "6. \u092a\u094d\u0930\u093e\u0915\u0943\u0924\u093f\u0915 \u092c\u0941\u0926\u094d\u0927\u093f\u092e\u0924\u094d\u0924\u093e (Naturalistic) (\u092a\u094d\u0930\u0915\u0943\u0924\u093f \u0915\u0940 \u0938\u092e\u091d)\n\u0938\u094d\u0924\u0930: \u0905\u091a\u094d\u091b\u093e\n\u2022 \u0915\u0943\u0937\u093f \u0938\u0947 \u091c\u0941\u0921\u093c\u0947 \u0915\u093e\u0930\u094d\u092f\n\u2022 \u0921\u0947\u0930\u0940 \u0914\u0930 \u092a\u0936\u0941\u092a\u093e\u0932\u0928 \u0915\u093e\u0930\u094d\u092f\n\u2022 \u0905\u091a\u094d\u091b\u0940 \u0917\u0941\u0923\u0935\u0924\u094d\u0924\u093e \u0935\u093e\u0932\u0947 \u0915\u091a\u094d\u091a\u0947 \u092e\u093e\u0932 \u0915\u0940 \u092a\u0939\u091a\u093e\u0928\n\u2022 \u092a\u094d\u0930\u093e\u0915\u0943\u0924\u093f\u0915 \u0909\u0924\u094d\u092a\u093e\u0926\u094b\u0902 \u0915\u0940 \u0924\u093e\u095b\u0917\u0940 \u0914\u0930 \u0917\u0941\u0923\u0935\u0924\u094d\u0924\u093e \u0915\u0940 \u091c\u093e\u0902\u091a",
    "7. \u0938\u0902\u0917\u0940\u0924\u093e\u0924\u094d\u092e\u0915 \u092c\u0941\u0926\u094d\u0927\u093f\u092e\u0924\u094d\u0924\u093e (Musical) (\u0932\u092f \u0914\u0930 \u0938\u0902\u0917\u0940\u0924)\n\u0938\u094d\u0924\u0930: \u092e\u0927\u094d\u092f\u092e\n\u2022 \u091c\u093e\u0917\u0930\u0942\u0915\u0924\u093e \u0917\u0940\u0924\u094b\u0902 \u092e\u0947\u0902 \u092d\u093e\u0917 \u0932\u0947\u0928\u093e\n\u2022 \u0917\u093e\u0901\u0935 \u0915\u0947 \u0938\u093e\u0902\u0938\u094d\u0915\u0943\u0924\u093f\u0915 \u0915\u093e\u0930\u094d\u092f\u0915\u094d\u0930\u092e\u094b\u0902 \u092e\u0947\u0902 \u0938\u0939\u092f\u094b\u0917\n\u2022 \u0938\u093e\u092e\u0941\u0926\u093e\u092f\u093f\u0915 \u0917\u0924\u093f\u0935\u093f\u0927\u093f\u092f\u094b\u0902 \u092e\u0947\u0902 \u092e\u0926\u0926 \u0915\u0930\u0928\u093e\n\u2022 \u0917\u0940\u0924 \u0914\u0930 \u092a\u094d\u0930\u0938\u094d\u0924\u0941\u0924\u093f\u092f\u094b\u0902 \u0915\u0947 \u092e\u093e\u0927\u094d\u092f\u092e \u0938\u0947 \u091c\u093e\u0917\u0930\u0942\u0915\u0924\u093e \u092b\u0948\u0932\u093e\u0928\u093e",
    "8. \u0930\u091a\u0928\u093e\u0924\u094d\u092e\u0915 \u092c\u0941\u0926\u094d\u0927\u093f\u092e\u0924\u094d\u0924\u093e (Creative) (\u0921\u093f\u091c\u093c\u093e\u0907\u0928 \u0914\u0930 \u0928\u0935\u093e\u091a\u093e\u0930)\n\u0938\u094d\u0924\u0930: \u092e\u0927\u094d\u092f\u092e\n\u2022 \u0928\u090f \u0909\u0924\u094d\u092a\u093e\u0926\u094b\u0902 \u0915\u0947 \u0935\u093f\u091a\u093e\u0930\u094b\u0902 \u092e\u0947\u0902 \u0938\u0939\u092f\u094b\u0917\n\u2022 \u0909\u0924\u094d\u092a\u093e\u0926 \u0921\u093f\u091c\u093c\u093e\u0907\u0928 \u0914\u0930 \u092b\u093f\u0928\u093f\u0936\u093f\u0902\u0917 \u092e\u0947\u0902 \u0938\u0939\u093e\u092f\u0924\u093e\n\u2022 \u092a\u0948\u0915\u0947\u091c\u093f\u0902\u0917 \u0914\u0930 \u092a\u094d\u0930\u0938\u094d\u0924\u0941\u0924\u093f \u092e\u0947\u0902 \u0938\u0941\u0927\u093e\u0930 \u0915\u0930\u0928\u093e\n\u2022 \u091b\u094b\u091f\u0947-\u091b\u094b\u091f\u0947 \u0930\u091a\u0928\u093e\u0924\u094d\u092e\u0915 \u0938\u0941\u091d\u093e\u0935 \u0926\u0947\u0928\u093e",
    "\u0906\u092a\u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u0909\u092a\u092f\u0941\u0915\u094d\u0924 \u0915\u093e\u0930\u094d\u092f \u0926\u093f\u0936\u093e",
    "\u0906\u092a \u090f\u0915 \u092e\u093f\u0932\u0928\u0938\u093e\u0930, \u0938\u0939\u092f\u094b\u0917\u0940 \u0914\u0930 \u092d\u0930\u094b\u0938\u0947\u092e\u0902\u0926 \u091f\u0940\u092e \u0938\u0926\u0938\u094d\u092f \u0939\u0948\u0902, \u091c\u094b \u0926\u0942\u0938\u0930\u094b\u0902 \u0915\u0947 \u0938\u093e\u0925 \u0905\u091a\u094d\u091b\u093e \u0915\u093e\u092e \u0915\u0930\u0924\u0947 \u0939\u0948\u0902 \u0914\u0930 \u0938\u092e\u0942\u0939 \u092e\u0947\u0902 \u0938\u0915\u093e\u0930\u093e\u0924\u094d\u092e\u0915 \u092e\u093e\u0939\u094c\u0932 \u092c\u0928\u093e\u090f \u0930\u0916\u0924\u0947 \u0939\u0948\u0902\u0964",
    "\u0906\u092a \u0909\u0928 \u092d\u0942\u092e\u093f\u0915\u093e\u0913\u0902 \u092e\u0947\u0902 \u0938\u092c\u0938\u0947 \u0905\u091a\u094d\u091b\u093e \u092a\u094d\u0930\u0926\u0930\u094d\u0936\u0928 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902 \u091c\u0939\u093e\u0901 \u091f\u0940\u092e\u0935\u0930\u094d\u0915, \u0938\u0902\u091a\u093e\u0930 \u0914\u0930 \u0928\u093f\u0930\u0902\u0924\u0930 \u092a\u094d\u0930\u092f\u093e\u0938 \u0915\u0940 \u0906\u0935\u0936\u094d\u092f\u0915\u0924\u093e \u0939\u094b\u0924\u0940 \u0939\u0948\u0964",
    "\u0906\u092a\u0915\u0940 \u0924\u093e\u0915\u0924\u0947\u0902 \u0906\u092a\u0915\u094b \u0907\u0928 \u0915\u093e\u0930\u094d\u092f\u094b\u0902 \u0915\u0947 \u0932\u093f\u090f \u0909\u092a\u092f\u0941\u0915\u094d\u0924 \u092c\u0928\u093e\u0924\u0940 \u0939\u0948\u0902:\n\u2022 \u0938\u092e\u0942\u0939 \u0915\u0947 \u0938\u092e\u0928\u094d\u0935\u092f \u0914\u0930 \u0917\u0924\u093f\u0935\u093f\u0927\u093f\u092f\u094b\u0902 \u092e\u0947\u0902 \u0938\u0939\u092f\u094b\u0917 \u0915\u0930\u0928\u093e\n\u2022 \u0909\u0924\u094d\u092a\u093e\u0926\u0928 \u0915\u093e\u0930\u094d\u092f\u094b\u0902 \u0915\u094b \u0938\u0902\u092d\u093e\u0932\u0928\u0947 \u092e\u0947\u0902 \u092e\u0926\u0926 \u0915\u0930\u0928\u093e\n\u2022 \u0938\u093e\u092e\u0941\u0926\u093e\u092f\u093f\u0915 \u0938\u0902\u092a\u0930\u094d\u0915 \u0914\u0930 \u091c\u093e\u0917\u0930\u0942\u0915\u0924\u093e \u0915\u093e\u0930\u094d\u092f\u0915\u094d\u0930\u092e\u094b\u0902 \u092e\u0947\u0902 \u092d\u093e\u0917 \u0932\u0947\u0928\u093e\n\u2022 \u0930\u093f\u0915\u0949\u0930\u094d\u0921 \u0930\u0916\u0928\u0947 \u0914\u0930 \u0938\u0902\u091a\u093e\u0930 \u0938\u0947 \u091c\u0941\u0921\u093c\u0947 \u0915\u093e\u0930\u094d\u092f\u094b\u0902 \u092e\u0947\u0902 \u0938\u0939\u092f\u094b\u0917 \u0915\u0930\u0928\u093e\n\u2022 \u0938\u092e\u0942\u0939 \u0915\u0947 \u0938\u0926\u0938\u094d\u092f\u094b\u0902 \u0915\u094b \u092d\u093e\u0917 \u0932\u0947\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u094d\u0930\u094b\u0924\u094d\u0938\u093e\u0939\u093f\u0924 \u0915\u0930\u0928\u093e",
    "\u0938\u0902\u091a\u093e\u0930 \u0915\u094c\u0936\u0932, \u0909\u0926\u094d\u092f\u092e \u0917\u0924\u093f\u0935\u093f\u0927\u093f\u092f\u094b\u0902 \u0914\u0930 \u0921\u093f\u091c\u093f\u091f\u0932 \u0930\u093f\u0915\u0949\u0930\u094d\u0921 \u0930\u0916\u0928\u0947 \u0915\u093e \u092a\u094d\u0930\u0936\u093f\u0915\u094d\u0937\u0923 \u0932\u0947\u0915\u0930 \u0906\u092a \u090f\u0915 \u092e\u0942\u0932\u094d\u092f\u0935\u093e\u0928 \u0938\u0926\u0938\u094d\u092f \u092c\u0928 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902, \u091c\u094b \u091f\u0940\u092e\u0935\u0930\u094d\u0915 \u0915\u094b \u092e\u095b\u092c\u0942\u0924 \u0915\u0930\u0924\u093e \u0939\u0948 \u0914\u0930 \u0935\u093f\u092d\u093f\u0928\u094d\u0928 \u0917\u0924\u093f\u0935\u093f\u0927\u093f\u092f\u094b\u0902 \u0915\u094b \u0906\u0917\u0947 \u092c\u0922\u093c\u093e\u0928\u0947 \u092e\u0947\u0902 \u092e\u0926\u0926 \u0915\u0930\u0924\u093e \u0939\u0948\u0964"
  ],
  "hi_Dominant_Compliant": [
    "\u0926\u0915\u094d\u0937 (DAKSH) \u0930\u093f\u092a\u094b\u0930\u094d\u091f",
    "\u0906\u092a\u0915\u0940 \u0935\u094d\u092f\u0915\u094d\u0924\u093f\u0924\u094d\u0935 \u0936\u0948\u0932\u0940\n\u092e\u0941\u0916\u094d\u092f \u0936\u0948\u0932\u0940: \u092a\u094d\u0930\u092e\u0941\u0916/\u0928\u0947\u0924\u0943\u0924\u094d\u0935\u0915\u093e\u0930\u0940 (Dominant)\n\u0926\u094d\u0935\u093f\u0924\u0940\u092f \u0936\u0948\u0932\u0940: \u0905\u0928\u0941\u092a\u093e\u0932\u0928 \u0915\u0930\u0928\u0947 \u0935\u093e\u0932\u0940 (Compliant)",
    "\u092f\u0939 \u0930\u093f\u092a\u094b\u0930\u094d\u091f \u0906\u092a\u0915\u0947 \u092c\u093e\u0930\u0947 \u092e\u0947\u0902 \u092f\u0939 \u091c\u093e\u0928\u0915\u093e\u0930\u0940 \u0926\u0947\u0924\u0940 \u0939\u0948:\n\u2022 \u0906\u092a \u0906\u0924\u094d\u092e\u0935\u093f\u0936\u094d\u0935\u093e\u0938\u0940 \u0939\u0948\u0902 \u0914\u0930 \u092a\u0930\u093f\u0923\u093e\u092e \u092a\u094d\u0930\u093e\u092a\u094d\u0924 \u0915\u0930\u0928\u0947 \u092a\u0930 \u0927\u094d\u092f\u093e\u0928 \u0926\u0947\u0924\u0947 \u0939\u0948\u0902\u0964\n\u2022 \u0906\u092a \u092a\u0939\u0932 \u0915\u0930\u0928\u093e \u0914\u0930 \u0915\u093e\u092e \u0915\u094b \u0906\u0917\u0947 \u092c\u0922\u093c\u093e\u0928\u093e \u092a\u0938\u0902\u0926 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902\u0964\n\u2022 \u0906\u092a \u0936\u0941\u0926\u094d\u0927\u0924\u093e, \u092f\u094b\u091c\u0928\u093e \u0914\u0930 \u0938\u0939\u0940 \u0924\u0930\u0940\u0915\u094b\u0902 \u0915\u094b \u092e\u0939\u0924\u094d\u0935 \u0926\u0947\u0924\u0947 \u0939\u0948\u0902\u0964\n\u2022 \u0906\u092a \u0915\u093e\u092e \u0915\u094b \u0938\u093e\u0935\u0927\u093e\u0928\u0940 \u0938\u0947 \u0915\u0930\u0928\u093e \u0914\u0930 \u0917\u0941\u0923\u0935\u0924\u094d\u0924\u093e \u092c\u0928\u093e\u090f \u0930\u0916\u0928\u093e \u092a\u0938\u0902\u0926 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902\u0964\n\u2022 \u0906\u092a \u095b\u093f\u092e\u094d\u092e\u0947\u0926\u093e\u0930\u0940 \u0932\u0947\u0928\u0947 \u092e\u0947\u0902 \u0938\u0939\u091c \u0939\u0948\u0902 \u0914\u0930 \u092f\u0939 \u0938\u0941\u0928\u093f\u0936\u094d\u091a\u093f\u0924 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902 \u0915\u093f \u0915\u093e\u092e \u0938\u0939\u0940 \u0924\u0930\u0940\u0915\u0947 \u0938\u0947 \u0939\u094b\u0964\n\u2022 \u0932\u094b\u0917 \u0906\u092a\u0915\u094b \u092e\u091c\u093c\u092c\u0942\u0924, \u0905\u0928\u0941\u0936\u093e\u0938\u093f\u0924 \u0914\u0930 \u092e\u0939\u0924\u094d\u0935\u092a\u0942\u0930\u094d\u0923 \u0915\u093e\u0930\u094d\u092f\u094b\u0902 \u0915\u094b \u0938\u0902\u092d\u093e\u0932\u0928\u0947 \u092e\u0947\u0902 \u092d\u0930\u094b\u0938\u0947\u092e\u0902\u0926 \u092e\u093e\u0928\u0924\u0947 \u0939\u0948\u0902\u0964",
    "\u0906\u092a\u0915\u0940 8 \u092a\u094d\u0930\u0915\u093e\u0930 \u0915\u0940 \u092c\u0941\u0926\u094d\u0927\u093f\u092e\u0924\u094d\u0924\u093e (Intelligences)",
    "1. \u0924\u093e\u0930\u094d\u0915\u093f\u0915\u2013\u0938\u0902\u0916\u094d\u092f\u093e\u0924\u094d\u092e\u0915 \u092c\u0941\u0926\u094d\u0927\u093f\u092e\u0924\u094d\u0924\u093e (Logical\u2013Numerical) (\u0938\u0902\u0916\u094d\u092f\u093e \u0914\u0930 \u0939\u093f\u0938\u093e\u092c-\u0915\u093f\u0924\u093e\u092c)\n\u0938\u094d\u0924\u0930: \u092e\u091c\u093c\u092c\u0942\u0924\n\u2022 \u0916\u093e\u0924\u094b\u0902 \u0914\u0930 \u0935\u093f\u0924\u094d\u0924\u0940\u092f \u0930\u093f\u0915\u0949\u0930\u094d\u0921 \u0915\u094b \u092c\u0928\u093e\u090f \u0930\u0916\u0928\u093e\n\u2022 \u092c\u091a\u0924 \u0914\u0930 \u090b\u0923 \u0915\u0947 \u0930\u093f\u0915\u0949\u0930\u094d\u0921 \u0915\u093e \u0939\u093f\u0938\u093e\u092c \u0930\u0916\u0928\u093e\n\u2022 \u0938\u094d\u091f\u0949\u0915 \u0914\u0930 \u0907\u0928\u094d\u0935\u0947\u0902\u091f\u0930\u0940 \u0930\u093f\u0915\u0949\u0930\u094d\u0921 \u0938\u0902\u092d\u093e\u0932\u0928\u093e\n\u2022 \u0932\u093e\u0917\u0924, \u092c\u091c\u091f \u0914\u0930 \u0932\u093e\u092d \u0915\u0940 \u092f\u094b\u091c\u0928\u093e \u092c\u0928\u093e\u0928\u093e",
    "2. \u092d\u093e\u0937\u093e\u0908 \u092c\u0941\u0926\u094d\u0927\u093f\u092e\u0924\u094d\u0924\u093e (Linguistic) (\u0938\u0902\u091a\u093e\u0930 \u0915\u094c\u0936\u0932)\n\u0938\u094d\u0924\u0930: \u0905\u091a\u094d\u091b\u093e\n\u2022 \u092f\u094b\u091c\u0928\u093e\u0913\u0902 \u0914\u0930 \u0928\u093f\u0930\u094d\u0926\u0947\u0936\u094b\u0902 \u0915\u094b \u0938\u094d\u092a\u0937\u094d\u091f \u0930\u0942\u092a \u0938\u0947 \u0938\u092e\u091d\u093e\u0928\u093e\n\u2022 \u0938\u092e\u0942\u0939 \u092c\u0948\u0920\u0915\u094b\u0902 \u092e\u0947\u0902 \u092c\u094b\u0932\u0928\u093e\n\u2022 \u0930\u093f\u0915\u0949\u0930\u094d\u0921 \u0914\u0930 \u0930\u093f\u092a\u094b\u0930\u094d\u091f \u0932\u093f\u0916\u0928\u093e\n\u2022 \u0917\u094d\u0930\u093e\u0939\u0915\u094b\u0902, \u0905\u0927\u093f\u0915\u093e\u0930\u093f\u092f\u094b\u0902 \u0914\u0930 \u0916\u0930\u0940\u0926\u093e\u0930\u094b\u0902 \u0938\u0947 \u0938\u0902\u0935\u093e\u0926 \u0915\u0930\u0928\u093e",
    "3. \u0935\u094d\u092f\u0915\u094d\u0924\u093f\u0917\u0924 \u0914\u0930 \u0938\u093e\u092e\u093e\u091c\u093f\u0915 \u092c\u0941\u0926\u094d\u0927\u093f\u092e\u0924\u094d\u0924\u093e (Personal & Social)\n\u0938\u094d\u0924\u0930: \u0905\u091a\u094d\u091b\u093e\n\u2022 \u091f\u0940\u092e \u0915\u0947 \u0938\u092e\u0928\u094d\u0935\u092f \u0914\u0930 \u0938\u0939\u092f\u094b\u0917 \u092e\u0947\u0902 \u0938\u0939\u093e\u092f\u0924\u093e \u0915\u0930\u0928\u093e\n\u2022 \u0938\u0926\u0938\u094d\u092f\u094b\u0902 \u0915\u094b \u092f\u094b\u091c\u0928\u093e\u0913\u0902 \u0914\u0930 \u095b\u093f\u092e\u094d\u092e\u0947\u0926\u093e\u0930\u0940 \u0915\u093e \u092a\u093e\u0932\u0928 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u094d\u0930\u0947\u0930\u093f\u0924 \u0915\u0930\u0928\u093e\n\u2022 \u0938\u092e\u0942\u0939 \u0917\u0924\u093f\u0935\u093f\u0927\u093f\u092f\u094b\u0902 \u092e\u0947\u0902 \u0905\u0928\u0941\u0936\u093e\u0938\u0928 \u092c\u0928\u093e\u090f \u0930\u0916\u0928\u093e\n\u2022 \u0938\u092e\u0942\u0939 \u0915\u094b \u0935\u094d\u092f\u0935\u0938\u094d\u0925\u093f\u0924 \u0924\u0930\u0940\u0915\u0947 \u0938\u0947 \u0915\u093e\u092e \u0915\u0930\u0928\u0947 \u092e\u0947\u0902 \u092e\u0926\u0926 \u0915\u0930\u0928\u093e",
    "4. \u0936\u093e\u0930\u0940\u0930\u093f\u0915\u2013\u0915\u094c\u0936\u0932 \u092c\u0941\u0926\u094d\u0927\u093f\u092e\u0924\u094d\u0924\u093e (Bodily\u2013Kinesthetic) (\u0935\u094d\u092f\u093e\u0935\u0939\u093e\u0930\u093f\u0915 \u0915\u093e\u0930\u094d\u092f \u0915\u094c\u0936\u0932)\n\u0938\u094d\u0924\u0930: \u0905\u091a\u094d\u091b\u093e\n\u2022 \u0909\u0924\u094d\u092a\u093e\u0926\u0928 \u0938\u0947 \u091c\u0941\u0921\u093c\u0947 \u0915\u093e\u0930\u094d\u092f\n\u2022 \u0916\u093e\u0926\u094d\u092f \u092a\u094d\u0930\u0938\u0902\u0938\u094d\u0915\u0930\u0923 (\u092b\u093c\u0942\u0921 \u092a\u094d\u0930\u094b\u0938\u0947\u0938\u093f\u0902\u0917)\n\u2022 \u0938\u093f\u0932\u093e\u0908 \u0914\u0930 \u091f\u0947\u0932\u0930\u093f\u0902\u0917\n\u2022 \u092a\u0948\u0915\u093f\u0902\u0917 \u0914\u0930 \u092b\u093f\u0928\u093f\u0936\u093f\u0902\u0917 \u0915\u093e \u0915\u093e\u092e\n\u2022 \u0917\u0941\u0923\u0935\u0924\u094d\u0924\u093e \u0915\u0940 \u091c\u093e\u0902\u091a",
    "5. \u0926\u0943\u0936\u094d\u092f\u2013\u0938\u094d\u0925\u093e\u0928\u093f\u0915 \u092c\u0941\u0926\u094d\u0927\u093f\u092e\u0924\u094d\u0924\u093e (Visual\u2013Spatial) (\u0921\u093f\u091c\u093c\u093e\u0907\u0928 \u0914\u0930 \u0935\u094d\u092f\u0935\u0938\u094d\u0925\u093e)\n\u0938\u094d\u0924\u0930: \u092e\u0927\u094d\u092f\u092e\n\u2022 \u0909\u0924\u094d\u092a\u093e\u0926 \u0915\u0940 \u092a\u0948\u0915\u0947\u091c\u093f\u0902\u0917 \u0914\u0930 \u092a\u094d\u0930\u0938\u094d\u0924\u0941\u0924\u093f \u092e\u0947\u0902 \u0938\u0939\u092f\u094b\u0917\n\u2022 \u092c\u093e\u095b\u093e\u0930 \u092f\u093e \u0938\u094d\u091f\u0949\u0932 \u092a\u0930 \u0909\u0924\u094d\u092a\u093e\u0926\u094b\u0902 \u0915\u094b \u0938\u091c\u093e\u0928\u093e\n\u2022 \u0938\u093e\u092e\u0917\u094d\u0930\u0940 \u0914\u0930 \u0909\u0924\u094d\u092a\u093e\u0926 \u0932\u0947\u0906\u0909\u091f \u0915\u094b \u0935\u094d\u092f\u0935\u0938\u094d\u0925\u093f\u0924 \u0915\u0930\u0928\u0947 \u092e\u0947\u0902 \u092e\u0926\u0926 \u0915\u0930\u0928\u093e",
    "6. \u092a\u094d\u0930\u093e\u0915\u0943\u0924\u093f\u0915 \u092c\u0941\u0926\u094d\u0927\u093f\u092e\u0924\u094d\u0924\u093e (Naturalistic) (\u092a\u094d\u0930\u0915\u0943\u0924\u093f \u0915\u0940 \u0938\u092e\u091d)\n\u0938\u094d\u0924\u0930: \u0905\u091a\u094d\u091b\u093e\n\u2022 \u0915\u0943\u0937\u093f \u0938\u0947 \u091c\u0941\u0921\u093c\u0947 \u0915\u093e\u0930\u094d\u092f\n\u2022 \u0921\u0947\u0930\u0940 \u0914\u0930 \u092a\u0936\u0941\u092a\u093e\u0932\u0928 \u0917\u0924\u093f\u0935\u093f\u0927\u093f\u092f\u093e\u0901\n\u2022 \u0905\u091a\u094d\u091b\u0940 \u0917\u0941\u0923\u0935\u0924\u094d\u0924\u093e \u0935\u093e\u0932\u0947 \u0915\u091a\u094d\u091a\u0947 \u092e\u093e\u0932 \u0915\u0940 \u092a\u0939\u091a\u093e\u0928\n\u2022 \u092a\u094d\u0930\u093e\u0915\u0943\u0924\u093f\u0915 \u0909\u0924\u094d\u092a\u093e\u0926\u094b\u0902 \u0915\u0940 \u0924\u093e\u091c\u093c\u0917\u0940\u0914\u0930 \u0917\u0941\u0923\u0935\u0924\u094d\u0924\u093e \u0915\u0940 \u091c\u093e\u0902\u091a",
    "7. \u0938\u0902\u0917\u0940\u0924\u093e\u0924\u094d\u092e\u0915 \u092c\u0941\u0926\u094d\u0927\u093f\u092e\u0924\u094d\u0924\u093e (Musical) (\u0932\u092f \u0914\u0930 \u0938\u0902\u0917\u0940\u0924)\n\u0938\u094d\u0924\u0930: \u0935\u093f\u0915\u0938\u093f\u0924 \u0939\u094b \u0930\u0939\u0940 \u0939\u0948\n\u2022 \u091c\u093e\u0917\u0930\u0942\u0915\u0924\u093e \u0917\u0940\u0924\u094b\u0902 \u092e\u0947\u0902 \u092d\u093e\u0917 \u0932\u0947\u0928\u093e\n\u2022 \u0917\u093e\u0901\u0935 \u0915\u0947 \u0938\u093e\u0902\u0938\u094d\u0915\u0943\u0924\u093f\u0915 \u0915\u093e\u0930\u094d\u092f\u0915\u094d\u0930\u092e\u094b\u0902 \u092e\u0947\u0902 \u0938\u0939\u092f\u094b\u0917\n\u2022 \u0938\u093e\u092e\u0941\u0926\u093e\u092f\u093f\u0915 \u0917\u0924\u093f\u0935\u093f\u0927\u093f\u092f\u094b\u0902 \u092e\u0947\u0902 \u092e\u0926\u0926 \u0915\u0930\u0928\u093e",
    "8. \u0930\u091a\u0928\u093e\u0924\u094d\u092e\u0915 \u092c\u0941\u0926\u094d\u0927\u093f\u092e\u0924\u094d\u0924\u093e (Creative) (\u0921\u093f\u091c\u093c\u093e\u0907\u0928 \u0914\u0930 \u0928\u0935\u093e\u091a\u093e\u0930)\n\u0938\u094d\u0924\u0930: \u092e\u0927\u094d\u092f\u092e\n\u2022 \u0928\u090f \u0909\u0924\u094d\u092a\u093e\u0926\u094b\u0902 \u0915\u0947 \u0935\u093f\u091a\u093e\u0930 \u0938\u0941\u091d\u093e\u0928\u093e\n\u2022 \u0921\u093f\u091c\u093c\u093e\u0907\u0928 \u0914\u0930 \u092b\u093f\u0928\u093f\u0936\u093f\u0902\u0917 \u0915\u093e\u0930\u094d\u092f \u092e\u0947\u0902 \u0938\u0939\u092f\u094b\u0917 \u0915\u0930\u0928\u093e\n\u2022 \u0909\u0924\u094d\u092a\u093e\u0926 \u0915\u0940 \u092a\u0948\u0915\u0947\u091c\u093f\u0902\u0917 \u0914\u0930 \u092a\u094d\u0930\u0938\u094d\u0924\u0941\u0924\u093f \u092e\u0947\u0902 \u0938\u0941\u0927\u093e\u0930 \u0915\u0930\u0928\u093e\n\u2022 \u0909\u0924\u094d\u092a\u093e\u0926\u094b\u0902 \u0915\u094b \u0917\u094d\u0930\u093e\u0939\u0915\u094b\u0902 \u0915\u0947 \u0932\u093f\u090f \u0905\u0927\u093f\u0915 \u0906\u0915\u0930\u094d\u0937\u0915 \u092c\u0928\u093e\u0928\u093e",
    "\u0906\u092a\u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u0909\u092a\u092f\u0941\u0915\u094d\u0924 \u0915\u093e\u0930\u094d\u092f \u0926\u093f\u0936\u093e",
    "\u0906\u092a \u090f\u0915 \u092e\u091c\u093c\u092c\u0942\u0924 \u0914\u0930 \u091c\u093c\u093f\u092e\u094d\u092e\u0947\u0926\u093e\u0930 \u0935\u094d\u092f\u0915\u094d\u0924\u093f \u0939\u0948\u0902, \u091c\u094b \u0928\u0947\u0924\u0943\u0924\u094d\u0935 \u0915\u0947 \u0938\u093e\u0925-\u0938\u093e\u0925 \u0938\u093e\u0935\u0927\u093e\u0928\u0940\u092a\u0942\u0930\u094d\u0935\u0915 \u092f\u094b\u091c\u0928\u093e \u0914\u0930 \u092c\u093e\u0930\u0940\u0915\u093f\u092f\u094b\u0902 \u092a\u0930 \u0927\u094d\u092f\u093e\u0928 \u0926\u0947\u0928\u0947 \u0915\u0940 \u0915\u094d\u0937\u092e\u0924\u093e \u0930\u0916\u0924\u0947 \u0939\u0948\u0902\u0964",
    "\u0906\u092a \u0909\u0928 \u092d\u0942\u092e\u093f\u0915\u093e\u0913\u0902 \u092e\u0947\u0902 \u0938\u092c\u0938\u0947 \u0905\u091a\u094d\u091b\u093e \u092a\u094d\u0930\u0926\u0930\u094d\u0936\u0928 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902 \u091c\u0939\u093e\u0901 \u0928\u093f\u0930\u094d\u0923\u092f \u0932\u0947\u0928\u093e, \u0938\u0902\u0917\u0920\u0928 \u0914\u0930 \u0917\u0941\u0923\u0935\u0924\u094d\u0924\u093e \u0928\u093f\u092f\u0902\u0924\u094d\u0930\u0923 \u0906\u0935\u0936\u094d\u092f\u0915 \u0939\u094b\u0924\u093e \u0939\u0948\u0964",
    "\u0906\u092a\u0915\u0940 \u0924\u093e\u0915\u0924\u0947\u0902 \u0906\u092a\u0915\u094b \u0907\u0928 \u0915\u093e\u0930\u094d\u092f\u094b\u0902 \u0915\u0947 \u0932\u093f\u090f \u0909\u092a\u092f\u0941\u0915\u094d\u0924 \u092c\u0928\u093e\u0924\u0940 \u0939\u0948\u0902:\n\u2022 \u0928\u0947\u0924\u093e \u092f\u093e \u0917\u0924\u093f\u0935\u093f\u0927\u093f \u0938\u092e\u0928\u094d\u0935\u092f\u0915 (Coordinator) \u0915\u0947 \u0930\u0942\u092a \u092e\u0947\u0902 \u0915\u093e\u092e \u0915\u0930\u0928\u093e\n\u2022 \u0909\u0924\u094d\u092a\u093e\u0926\u0928 \u0915\u0940 \u092f\u094b\u091c\u0928\u093e \u0914\u0930 \u0928\u093f\u0917\u0930\u093e\u0928\u0940 \u0915\u0930\u0928\u093e\n\u2022 \u0935\u093f\u0924\u094d\u0924\u0940\u092f \u0930\u093f\u0915\u0949\u0930\u094d\u0921 \u0914\u0930 \u0926\u0938\u094d\u0924\u093e\u0935\u0947\u091c\u093c \u092c\u0928\u093e\u090f \u0930\u0916\u0928\u093e\n\u2022 \u0909\u0924\u094d\u092a\u093e\u0926 \u0915\u0940 \u0917\u0941\u0923\u0935\u0924\u094d\u0924\u093e \u0914\u0930 \u092e\u093e\u0928\u0915\u094b\u0902 \u0915\u0940 \u0928\u093f\u0917\u0930\u093e\u0928\u0940 \u0915\u0930\u0928\u093e\n\u2022 \u0909\u0926\u094d\u092f\u092e \u0915\u0940 \u092f\u094b\u091c\u0928\u093e \u0914\u0930 \u0938\u0902\u091a\u093e\u0932\u0928 \u092e\u0947\u0902 \u0938\u0939\u092f\u094b\u0917 \u0915\u0930\u0928\u093e",
    "\u0909\u0926\u094d\u092f\u092e \u092a\u094d\u0930\u092c\u0902\u0927\u0928, \u0935\u093f\u0924\u094d\u0924\u0940\u092f \u092f\u094b\u091c\u0928\u093e \u0914\u0930 \u0921\u093f\u091c\u093f\u091f\u0932 \u0930\u093f\u0915\u0949\u0930\u094d\u0921 \u0930\u0916\u0928\u0947 \u0915\u093e \u092a\u094d\u0930\u0936\u093f\u0915\u094d\u0937\u0923 \u0932\u0947\u0915\u0930 \u0906\u092a \u090f\u0915 \u092e\u0939\u0924\u094d\u0935\u092a\u0942\u0930\u094d\u0923 \u0938\u0926\u0938\u094d\u092f \u092c\u0928 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902, \u091c\u094b \u0938\u0902\u0917\u0920\u0928 \u0915\u0947 \u0915\u093e\u0930\u094d\u092f\u094b\u0902 \u0915\u094b \u0915\u0941\u0936\u0932\u0924\u093e \u0938\u0947 \u091a\u0932\u093e\u0928\u0947 \u0914\u0930 \u0938\u092b\u0932\u0924\u093e\u092a\u0942\u0930\u094d\u0935\u0915 \u0906\u0917\u0947 \u092c\u0922\u093c\u093e\u0928\u0947 \u092e\u0947\u0902 \u092e\u0926\u0926 \u0915\u0930\u0924\u093e \u0939\u0948\u0964",
    "Top of Form",
    "Bottom of Form"
  ],
